#include "tcpconfigeditor.h"

#include "ui_tcpconfigeditor.h"   // generated by uic from tcpconfigeditor.ui

TcpConfigEditor::TcpConfigEditor(QWidget *parent) : iwp::FormConfigEditor(parent)
{
    // The layout, labels, ranges and defaults are in tcpconfigeditor.ui; here only the keys of the
    // config are bound to the widgets.
    auto *page = new QWidget;
    Ui::TcpConfigEditor ui;
    ui.setupUi(page);
    setupPage(page);

    bindText(QStringLiteral("host"), ui.hostEdit);
    bindInt(QStringLiteral("port"), ui.portSpin);
}

QString TcpConfigEditor::validate() const
{
    return config().value(QStringLiteral("host")).toString().isEmpty()
               ? tr("Enter the host name or address") : QString();
}
